// Filtrer par score minimum et limiter le batch
const SCORE_MIN = 60;
const BATCH_MAX = 20;

const prospects = $input.all();
const filtres = prospects
  .filter(p => {
    const score = parseInt(p.json.SCORE || '0');
    const email = p.json.EMAIL || '';
    return score >= SCORE_MIN && email.includes('@');
  })
  .sort((a, b) => parseInt(b.json.SCORE || '0') - parseInt(a.json.SCORE || '0'))
  .slice(0, BATCH_MAX);

console.log(`${filtres.length} prospects sélectionnés sur ${prospects.length} totaux`);
return filtres;

// Charger le prompt depuis le fichier de templates
// (En production, stocker les prompts dans N8N Variables)
const prospect = $input.first().json;

const secteur = prospect.SECTEUR || 'Services';
const specificites = {
  'Restauration':   'Dans la restauration, les avis Google sont critiques pour le remplissage. Un avis négatif sans réponse coûte en moyenne 30% de clients potentiels.',
  'Beauté':         'Dans la beauté, la confiance et l image sont primordiales. Les avis sans réponse donnent l impression d un salon qui ne se soucie pas de ses clientes.',
  'Automobile':     'Dans l automobile, les clients lisent les avis avant chaque grosse décision d achat ou de réparation.',
  'Auto-école':     'Dans les auto-écoles, les parents vérifient les avis avant d inscrire leurs enfants.',
  'Santé':          'Dans la santé, répondre aux avis patients renforce la crédibilité professionnelle.',
  'Artisanat':      'Dans l artisanat, les avis Google sont la principale source de nouveaux clients.',
  'Hôtellerie':     'Dans l hôtellerie, Booking et Google valorisent les établissements qui répondent aux avis.',
  'Services':       'Dans les services, les décideurs lisent les avis avant de signer.',
  'Sport & Loisirs': 'Dans le sport et les loisirs, la communauté en ligne est très active.',
  'Commerce':       'Dans le commerce de proximité, les avis Google influencent directement le trafic en magasin.'
};

const spec = specificites[secteur] || '';

// Mapping secteur → ID pour la page preview
const secteurIds = {
  'Restauration': 'restauration',
  'Beauté':       'beaute',
  'Automobile':   'automobile',
  'Auto-école':   'auto_ecole',
  'Santé':        'sante',
  'Artisanat':    'artisanat',
  'Hôtellerie':   'hotellerie',
  'Services':     'services',
  'Sport & Loisirs': 'services',
  'Commerce':     'services'
};
const secteurId = secteurIds[secteur] || 'services';

// Construction de l'URL d'aperçu personnalisé
const previewParams = new URLSearchParams({
  nom:       prospect.ENTREPRISE || '',
  secteur:   secteurId,
  ville:     prospect.VILLE || '',
  note:      prospect.NOTE_GOOGLE || '4.2',
  nb_avis:   prospect.NB_AVIS || '0',
  sans_rep:  prospect.AVIS_SANS_REPONSE || '0',
  telephone: prospect.TELEPHONE || '',
  adresse:   prospect.ADRESSE || '',
  prenom:    prospect.PRENOM || ''
});
const urlPreviewSite = `https://replyshield.io/preview.html?${previewParams.toString()}`;

const promptObjet = `Génère 1 objet d'email percutant (max 60 caractères) pour prospecter ${prospect.PRENOM || 'le dirigeant'} qui dirige ${prospect.ENTREPRISE} (${secteur}) à ${prospect.VILLE}. Son établissement a ${prospect.NB_AVIS} avis Google dont ${prospect.AVIS_SANS_REPONSE} (${prospect.PCT_SANS_REPONSE}%) sans réponse. L'email propose ReplyShield : Répondez automatiquement à tous vos avis Google en 30 secondes grâce à l'IA. L'objet doit mentionner un chiffre réel et créer de l'urgence. Réponds uniquement avec l'objet, rien d'autre.`;

const promptCorps = `Rédige un email de prospection B2B pour ${prospect.PRENOM || 'le dirigeant'}, dirigeant de ${prospect.ENTREPRISE} (${secteur}) à ${prospect.VILLE}.

Contexte sectoriel : ${spec}

Chiffres réels de cet établissement :
- ${prospect.NB_AVIS} avis Google au total
- ${prospect.AVIS_SANS_REPONSE} avis sans réponse (${prospect.PCT_SANS_REPONSE}%)
- Note Google actuelle : ${prospect.NOTE_GOOGLE}/5

Produit à promouvoir : ReplyShield
Pitch : Répondez automatiquement à tous vos avis Google en 30 secondes grâce à l'IA
Offre : 14 jours gratuits, sans carte bancaire
Lien essai gratuit : https://replyshield.io/essai-gratuit
Aperçu site web personnalisé pour cet établissement : ${urlPreviewSite}

Contraintes :
- Commence par quelque chose de percutant qui cite un chiffre réel (pas 'Bonjour [Prenom]' classique)
- 3 paragraphes max, 120 mots max
- Mentionne l'aperçu du site avec cette formulation exacte : 'J'ai créé un aperçu gratuit de votre futur site web : ${urlPreviewSite}'
- 1 seul call-to-action principal à la fin vers https://replyshield.io/essai-gratuit
- Ton : direct, humain, pas de jargon marketing
- Signe avec 'L'équipe ReplyShield'

Réponds uniquement avec le corps de l'email, sans objet.`;

return [{ json: { ...prospect, promptObjet, promptCorps, urlPreviewSite } }];

