// Fusionner objet + corps générés par Claude
const prospect   = $('Préparer les prompts Claude').first().json;
const respObjet  = $('Claude — Générer objet email').first().json;
const respCorps  = $('Claude — Générer corps email').first().json;

const objet = respObjet.content?.[0]?.text?.trim() || `${prospect.PRENOM}, vos avis attendent une réponse`;
const corps = respCorps.content?.[0]?.text?.trim() || '';

return [{ json: { ...prospect, email_objet: objet, email_corps: corps } }];

